#!/usr/bin/env python3

import yaml

print("|Model Name|Image Name|")
print("|---|---|")

with open(".travis.yml", 'r') as stream:
    try:
        travis = yaml.safe_load(stream)
        for model in travis['jobs']['include']:
            if model['stage'] != "buildanddeploy":
                continue

            model_name = model['env']['MODEL_NAME']
            tag = model_name
            if 'MODEL_TAG_NAME' in model['env']:
                tag = model['env']['MODEL_TAG_NAME']

            image_name = 'semitechnologies/ner-transformers:' + tag
            link = 'https://huggingface.co/' + model_name
            print("|`{}` ([Info]({}))|`{}`|".format(model_name, link, image_name))
    except yaml.YAMLError as exc:
        print(exc)

import unittest
import requests
import time

class SmokeTest(unittest.TestCase):
    def _waitForStartup(self):
        url = 'http://localhost:8000/.well-known/ready'

        for i in range(0, 100):
            try:
                res = requests.get(url)
                if res.status_code == 204:
                    return
                else:
                    raise Exception(
                            "status code is {}".format(res.status_code))
            except Exception as e:
                print("Attempt {}: {}".format(i, e))
                time.sleep(1)

        raise Exception("did not start up")

    def testNer(self):
        self._waitForStartup()
        url = 'http://localhost:8000/ner/'

        req_body = {'text': 'John works in Berlin'}
        res = requests.post(url, json=req_body)
        resBody = res.json()

        expected_result = {'text': 'John works in Berlin', 'tokens': [{'word': 'John', 'entity': 'I-PER', 'certainty': 0.9974473714828491, 'startPosition': 0, 'endPosition': 4}, {'word': 'Berlin', 'entity': 'I-LOC', 'certainty': 0.9994735717773438, 'startPosition': 14, 'endPosition': 20}]}

        self.assertEqual(200, res.status_code)
        self.assertEqual(req_body['text'], resBody['text'])
        self.assertEqual(len(resBody['tokens']), len(expected_result['tokens']))

        req_body = {'text': 'Hello how are you doing'}
        res = requests.post(url, json=req_body)
        resBody = res.json()

        expected_result = {'text': 'Hello how are you doing', 'tokens': []}

        self.assertEqual(200, res.status_code)
        self.assertEqual(req_body['text'], resBody['text'])
        self.assertCountEqual(resBody['tokens'], expected_result['tokens'])

        req_body = {'text': ''}
        res = requests.post(url, json=req_body)
        resBody = res.json()

        expected_result = {'text': '', 'tokens': None}

        self.assertEqual(200, res.status_code)
        self.assertEqual(req_body['text'], resBody['text'])
        self.assertTrue(resBody['tokens'] is None or resBody['tokens'] == [])


if __name__ == "__main__":
    unittest.main()

import json
from transformers import AutoConfig

class Meta:
    def __init__(self, model_path: str, model_name: str):
        if model_name.startswith("urchade"):
            with open(f"{model_path}/model_config.json", "r") as f:
                self.config = json.load(f)
        else:
            config = AutoConfig.from_pretrained(model_path)
            self.config = config.to_dict()

    def get(self):
        return {
            'model': self.config
        }

import os
from logging import getLogger
from fastapi import FastAPI, Response, status
from ner import Ner, NerInput
from meta import Meta

app = FastAPI()
ner : Ner
meta_config : Meta
logger = getLogger('uvicorn')


@app.on_event("startup")
def startup_event():
    global ner
    global meta_config

    model_dir = "./models/model"

    def get_model_name() -> (str):
        if os.path.exists(f"{model_dir}/model_name"):
            with open(f"{model_dir}/model_name", "r") as f:
                model_name = f.read()
                return model_name
        return ""

    cuda_env = os.getenv("ENABLE_CUDA")
    cuda_support=False
    cuda_core=""

    if cuda_env is not None and cuda_env == "true" or cuda_env == "1":
        cuda_support=True
        cuda_core = os.getenv("CUDA_CORE")
        if cuda_core is None or cuda_core == "":
            cuda_core = "cuda:0"
        logger.info(f"CUDA_CORE set to {cuda_core}")
    else:
        logger.info("Running on CPU")

    ner = Ner(model_dir, get_model_name(), cuda_support, cuda_core)
    meta_config = Meta(model_dir, get_model_name())


@app.get("/.well-known/live", response_class=Response)
@app.get("/.well-known/ready", response_class=Response)
def live_and_ready(response: Response):
    response.status_code = status.HTTP_204_NO_CONTENT


@app.get("/meta")
def meta():
    return meta_config.get()


@app.post("/ner")
@app.post("/ner/")
async def read_item(item: NerInput, response: Response):
    try:
        tokens = await ner.do(item)

        jsonToReturn = {
            "text": item.text,
            "tokens": tokens
        }

        '''
        tokens = [{
                "entity": "string",
                "word": "string",
                "certainty": 0.9     # float
                "startPosition": 1   # int
                "endPosition: 2      # int
            }] # Or None

        text = "string"
        '''

        return jsonToReturn

    except Exception as e:
        logger.exception(
            'Something went wrong while extracting data.'
        )
        response.status_code = status.HTTP_500_INTERNAL_SERVER_ERROR
        return {"error": str(e)}
